"""SQLite-backed order fulfillment service."""

from __future__ import annotations

import contextlib
import math
import sqlite3

__all__ = ["OrderError", "OrderService"]

_STATUSES = ("pending", "paid", "shipped", "cancelled")

_EXPECTED_TABLES = {
    "meta": ["key", "value"],
    "stock": ["sku", "available"],
    "orders": [
        "order_id",
        "idempotency_key",
        "status",
        "total_cents",
        "payment_id",
        "created_at",
        "updated_at",
    ],
    "order_items": ["order_id", "sku", "quantity", "unit_price_cents"],
}

_SCHEMA_SQL = (
    "CREATE TABLE meta ("
    " key TEXT PRIMARY KEY,"
    " value TEXT NOT NULL)",
    "CREATE TABLE stock ("
    " sku TEXT PRIMARY KEY,"
    " available INTEGER NOT NULL CHECK (available >= 0))",
    "CREATE TABLE orders ("
    " order_id TEXT PRIMARY KEY,"
    " idempotency_key TEXT NOT NULL UNIQUE,"
    " status TEXT NOT NULL CHECK (status IN ('pending','paid','shipped','cancelled')),"
    " total_cents INTEGER NOT NULL CHECK (total_cents >= 0),"
    " payment_id TEXT UNIQUE,"
    " created_at NOT NULL,"
    " updated_at NOT NULL)",
    "CREATE TABLE order_items ("
    " order_id TEXT NOT NULL REFERENCES orders(order_id),"
    " sku TEXT NOT NULL,"
    " quantity INTEGER NOT NULL CHECK (quantity > 0),"
    " unit_price_cents INTEGER NOT NULL CHECK (unit_price_cents >= 0),"
    " PRIMARY KEY (order_id, sku))",
)


class OrderError(Exception):
    """Stable order-domain error with a code, message, and details."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        super().__init__(message)
        self.code = code
        self.message = message
        self.details = dict(details) if details is not None else {}


def _require_str(name: str, value: object) -> str:
    if not isinstance(value, str) or value.strip() == "":
        raise OrderError(
            "INVALID_INPUT",
            f"{name} must be a non-empty, non-whitespace string",
            {"field": name},
        )
    return value


def _require_int(name: str, value: object, minimum: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise OrderError("INVALID_INPUT", f"{name} must be an integer", {"field": name})
    if value < minimum:
        raise OrderError(
            "INVALID_INPUT", f"{name} must be >= {minimum}", {"field": name}
        )
    return value


def _validate_items(items: object) -> list[tuple[str, int, int]]:
    if not isinstance(items, list) or not items:
        raise OrderError(
            "INVALID_INPUT", "items must be a non-empty list", {"field": "items"}
        )
    canonical: list[tuple[str, int, int]] = []
    seen: set[str] = set()
    for item in items:
        if not isinstance(item, dict):
            raise OrderError(
                "INVALID_INPUT", "each item must be an object", {"field": "items"}
            )
        if set(item) != {"sku", "quantity", "unit_price_cents"}:
            raise OrderError(
                "INVALID_INPUT",
                "each item must have exactly sku, quantity, unit_price_cents",
                {"field": "items"},
            )
        sku = _require_str("items.sku", item["sku"])
        quantity = _require_int("items.quantity", item["quantity"], 1)
        unit_price = _require_int("items.unit_price_cents", item["unit_price_cents"], 0)
        if sku in seen:
            raise OrderError(
                "INVALID_INPUT", "duplicate sku in items", {"sku": sku}
            )
        seen.add(sku)
        canonical.append((sku, quantity, unit_price))
    canonical.sort(key=lambda triple: triple[0])
    return canonical


class OrderService:
    """SQLite-backed order service with atomic stock reservation."""

    def __init__(self, db_path, *, clock, id_factory):
        if not callable(clock):
            raise OrderError("INVALID_DEPENDENCY", "clock must be callable", {})
        if not callable(id_factory):
            raise OrderError("INVALID_DEPENDENCY", "id_factory must be callable", {})
        self._clock = clock
        self._id_factory = id_factory
        try:
            self._conn = sqlite3.connect(db_path, timeout=15.0)
        except sqlite3.Error as exc:
            raise OrderError("STORAGE_ERROR", "cannot open database", {"error": str(exc)})
        self._conn.isolation_level = None
        self._conn.row_factory = sqlite3.Row
        try:
            self._conn.execute("PRAGMA busy_timeout = 15000")
            self._init_schema()
        except OrderError:
            self._conn.close()
            raise
        except sqlite3.DatabaseError as exc:
            self._conn.close()
            raise OrderError(
                "SCHEMA_MISMATCH", "existing file is not a compatible database",
                {"error": str(exc)},
            )
        except sqlite3.Error as exc:
            self._conn.close()
            raise OrderError("STORAGE_ERROR", "schema initialization failed", {"error": str(exc)})

    # -- schema ------------------------------------------------------------

    def _init_schema(self) -> None:
        with self._txn():
            rows = self._conn.execute(
                "SELECT name, type FROM sqlite_master "
                "WHERE name NOT LIKE 'sqlite_%'"
            ).fetchall()
            names = {row["name"] for row in rows if row["type"] == "table"}
            all_names = {row["name"] for row in rows}
            if not all_names:
                for statement in _SCHEMA_SQL:
                    self._conn.execute(statement)
                self._conn.execute(
                    "INSERT INTO meta (key, value) VALUES ('schema_version', '1')"
                )
                return
            if names != set(_EXPECTED_TABLES) or all_names != names:
                raise OrderError(
                    "SCHEMA_MISMATCH", "unknown or incompatible schema",
                    {"tables": sorted(all_names)},
                )
            for table, expected_cols in _EXPECTED_TABLES.items():
                cols = [
                    row["name"]
                    for row in self._conn.execute(f"PRAGMA table_info({table})")
                ]
                if cols != expected_cols:
                    raise OrderError(
                        "SCHEMA_MISMATCH", "incompatible table layout",
                        {"table": table, "columns": cols},
                    )
            row = self._conn.execute(
                "SELECT value FROM meta WHERE key = 'schema_version'"
            ).fetchone()
            if row is None or row["value"] != "1":
                raise OrderError(
                    "SCHEMA_MISMATCH", "unknown schema version",
                    {"schema_version": None if row is None else row["value"]},
                )

    # -- helpers -----------------------------------------------------------

    @contextlib.contextmanager
    def _txn(self):
        try:
            self._conn.execute("BEGIN IMMEDIATE")
        except sqlite3.DatabaseError:
            raise
        try:
            yield
        except BaseException:
            try:
                self._conn.execute("ROLLBACK")
            except sqlite3.Error:
                pass
            raise
        else:
            self._conn.execute("COMMIT")

    def _read_clock(self):
        try:
            value = self._clock()
        except Exception as exc:
            raise OrderError("INVALID_DEPENDENCY", "clock raised an exception", {"error": str(exc)})
        if (
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or not math.isfinite(value)
        ):
            raise OrderError("INVALID_DEPENDENCY", "clock must return a finite number", {})
        return value

    def _new_order_id(self) -> str:
        for _ in range(3):
            try:
                candidate = self._id_factory()
            except Exception as exc:
                raise OrderError(
                    "INVALID_DEPENDENCY", "id_factory raised an exception",
                    {"error": str(exc)},
                )
            if not isinstance(candidate, str) or candidate.strip() == "":
                raise OrderError(
                    "INVALID_DEPENDENCY",
                    "id_factory must return a non-empty, non-whitespace string",
                    {},
                )
            row = self._conn.execute(
                "SELECT 1 FROM orders WHERE order_id = ?", (candidate,)
            ).fetchone()
            if row is None:
                return candidate
        raise OrderError("ID_COLLISION", "id_factory produced only duplicate ids", {})

    def _fetch_order_row(self, order_id: str):
        return self._conn.execute(
            "SELECT * FROM orders WHERE order_id = ?", (order_id,)
        ).fetchone()

    def _load_items(self, order_id: str) -> list[tuple[str, int, int]]:
        rows = self._conn.execute(
            "SELECT sku, quantity, unit_price_cents FROM order_items "
            "WHERE order_id = ? ORDER BY sku",
            (order_id,),
        ).fetchall()
        return [(row["sku"], row["quantity"], row["unit_price_cents"]) for row in rows]

    def _order_public(self, row, items: list[tuple[str, int, int]]) -> dict:
        return {
            "order_id": row["order_id"],
            "idempotency_key": row["idempotency_key"],
            "status": row["status"],
            "items": [
                {"sku": sku, "quantity": quantity, "unit_price_cents": unit_price}
                for sku, quantity, unit_price in items
            ],
            "total_cents": row["total_cents"],
            "payment_id": row["payment_id"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
        }

    # -- public API --------------------------------------------------------

    def set_stock(self, sku: str, quantity: int) -> dict:
        _require_str("sku", sku)
        _require_int("quantity", quantity, 0)
        try:
            with self._txn():
                self._conn.execute(
                    "INSERT INTO stock (sku, available) VALUES (?, ?) "
                    "ON CONFLICT(sku) DO UPDATE SET available = excluded.available",
                    (sku, quantity),
                )
        except sqlite3.Error as exc:
            raise OrderError("STORAGE_ERROR", "stock update failed", {"error": str(exc)})
        return {"sku": sku, "available": quantity}

    def create_order(self, idempotency_key: str, items: list[dict]) -> dict:
        _require_str("idempotency_key", idempotency_key)
        canonical = _validate_items(items)
        total_cents = sum(quantity * price for _, quantity, price in canonical)
        try:
            with self._txn():
                row = self._conn.execute(
                    "SELECT * FROM orders WHERE idempotency_key = ?",
                    (idempotency_key,),
                ).fetchone()
                if row is not None:
                    existing = self._load_items(row["order_id"])
                    if existing == canonical:
                        return self._order_public(row, existing)
                    raise OrderError(
                        "IDEMPOTENCY_CONFLICT",
                        "idempotency key reused with different items",
                        {"idempotency_key": idempotency_key},
                    )
                for sku, quantity, _ in canonical:
                    stock_row = self._conn.execute(
                        "SELECT available FROM stock WHERE sku = ?", (sku,)
                    ).fetchone()
                    if stock_row is None or stock_row["available"] < quantity:
                        raise OrderError(
                            "INSUFFICIENT_STOCK",
                            "insufficient stock for sku",
                            {
                                "sku": sku,
                                "requested": quantity,
                                "available": 0 if stock_row is None else stock_row["available"],
                            },
                        )
                order_id = self._new_order_id()
                now = self._read_clock()
                self._conn.execute(
                    "INSERT INTO orders (order_id, idempotency_key, status, "
                    "total_cents, payment_id, created_at, updated_at) "
                    "VALUES (?, ?, 'pending', ?, NULL, ?, ?)",
                    (order_id, idempotency_key, total_cents, now, now),
                )
                for sku, quantity, unit_price in canonical:
                    self._conn.execute(
                        "INSERT INTO order_items (order_id, sku, quantity, "
                        "unit_price_cents) VALUES (?, ?, ?, ?)",
                        (order_id, sku, quantity, unit_price),
                    )
                    self._conn.execute(
                        "UPDATE stock SET available = available - ? WHERE sku = ?",
                        (quantity, sku),
                    )
                row = self._fetch_order_row(order_id)
                return self._order_public(row, canonical)
        except sqlite3.Error as exc:
            raise OrderError("STORAGE_ERROR", "create_order failed", {"error": str(exc)})

    def pay_order(self, order_id: str, payment_id: str, amount_cents: int) -> dict:
        _require_str("order_id", order_id)
        _require_str("payment_id", payment_id)
        _require_int("amount_cents", amount_cents, 0)
        try:
            with self._txn():
                row = self._fetch_order_row(order_id)
                if row is None:
                    raise OrderError(
                        "NOT_FOUND", "order not found", {"order_id": order_id}
                    )
                if row["payment_id"] is not None:
                    if (
                        payment_id == row["payment_id"]
                        and amount_cents == row["total_cents"]
                    ):
                        return self._order_public(row, self._load_items(order_id))
                    raise OrderError(
                        "PAYMENT_CONFLICT",
                        "payment conflicts with the recorded payment",
                        {"order_id": order_id},
                    )
                if row["status"] != "pending":
                    raise OrderError(
                        "INVALID_STATE",
                        f"cannot pay a {row['status']} order",
                        {"order_id": order_id, "status": row["status"]},
                    )
                other = self._conn.execute(
                    "SELECT order_id FROM orders WHERE payment_id = ?",
                    (payment_id,),
                ).fetchone()
                if other is not None:
                    raise OrderError(
                        "PAYMENT_CONFLICT",
                        "payment id already used by another order",
                        {"payment_id": payment_id},
                    )
                if amount_cents != row["total_cents"]:
                    raise OrderError(
                        "AMOUNT_MISMATCH",
                        "amount does not match order total",
                        {"expected": row["total_cents"], "actual": amount_cents},
                    )
                now = self._read_clock()
                self._conn.execute(
                    "UPDATE orders SET status = 'paid', payment_id = ?, "
                    "updated_at = ? WHERE order_id = ?",
                    (payment_id, now, order_id),
                )
                row = self._fetch_order_row(order_id)
                return self._order_public(row, self._load_items(order_id))
        except sqlite3.Error as exc:
            raise OrderError("STORAGE_ERROR", "pay_order failed", {"error": str(exc)})

    def cancel_order(self, order_id: str) -> dict:
        _require_str("order_id", order_id)
        try:
            with self._txn():
                row = self._fetch_order_row(order_id)
                if row is None:
                    raise OrderError(
                        "NOT_FOUND", "order not found", {"order_id": order_id}
                    )
                items = self._load_items(order_id)
                if row["status"] == "cancelled":
                    return self._order_public(row, items)
                if row["status"] == "shipped":
                    raise OrderError(
                        "INVALID_STATE",
                        "cannot cancel a shipped order",
                        {"order_id": order_id, "status": "shipped"},
                    )
                now = self._read_clock()
                for sku, quantity, _ in items:
                    cursor = self._conn.execute(
                        "UPDATE stock SET available = available + ? WHERE sku = ?",
                        (quantity, sku),
                    )
                    if cursor.rowcount == 0:
                        self._conn.execute(
                            "INSERT INTO stock (sku, available) VALUES (?, ?)",
                            (sku, quantity),
                        )
                self._conn.execute(
                    "UPDATE orders SET status = 'cancelled', updated_at = ? "
                    "WHERE order_id = ?",
                    (now, order_id),
                )
                row = self._fetch_order_row(order_id)
                return self._order_public(row, items)
        except sqlite3.Error as exc:
            raise OrderError("STORAGE_ERROR", "cancel_order failed", {"error": str(exc)})

    def ship_order(self, order_id: str) -> dict:
        _require_str("order_id", order_id)
        try:
            with self._txn():
                row = self._fetch_order_row(order_id)
                if row is None:
                    raise OrderError(
                        "NOT_FOUND", "order not found", {"order_id": order_id}
                    )
                items = self._load_items(order_id)
                if row["status"] == "shipped":
                    return self._order_public(row, items)
                if row["status"] != "paid":
                    raise OrderError(
                        "INVALID_STATE",
                        f"cannot ship a {row['status']} order",
                        {"order_id": order_id, "status": row["status"]},
                    )
                now = self._read_clock()
                self._conn.execute(
                    "UPDATE orders SET status = 'shipped', updated_at = ? "
                    "WHERE order_id = ?",
                    (now, order_id),
                )
                row = self._fetch_order_row(order_id)
                return self._order_public(row, items)
        except sqlite3.Error as exc:
            raise OrderError("STORAGE_ERROR", "ship_order failed", {"error": str(exc)})

    def get_order(self, order_id: str) -> dict:
        _require_str("order_id", order_id)
        try:
            row = self._fetch_order_row(order_id)
            if row is None:
                raise OrderError("NOT_FOUND", "order not found", {"order_id": order_id})
            return self._order_public(row, self._load_items(order_id))
        except sqlite3.Error as exc:
            raise OrderError("STORAGE_ERROR", "get_order failed", {"error": str(exc)})

