"""Order fulfillment JSON CLI entry point."""

from __future__ import annotations

import json
import sys
import time
import uuid

from . import OrderError, OrderService

_FIELDS = {
    "stock": {"sku", "quantity"},
    "create": {"idempotency_key", "items"},
    "pay": {"order_id", "payment_id", "amount_cents"},
    "cancel": {"order_id"},
    "ship": {"order_id"},
    "get": {"order_id"},
}


def _emit(obj: dict, exit_code: int) -> int:
    data = json.dumps(
        obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False
    )
    sys.stdout.buffer.write(data.encode("utf-8") + b"\n")
    sys.stdout.buffer.flush()
    return exit_code


def _emit_error(err: OrderError) -> int:
    envelope = {
        "ok": False,
        "error": {"code": err.code, "message": err.message, "details": err.details},
    }
    exit_code = 3 if err.code == "STORAGE_ERROR" else 2
    try:
        return _emit(envelope, exit_code)
    except (TypeError, ValueError):
        envelope["error"]["details"] = {}
        return _emit(envelope, exit_code)


def _read_stdin_object() -> dict:
    try:
        text = sys.stdin.buffer.read().decode("utf-8")
    except UnicodeDecodeError:
        raise OrderError("INVALID_INPUT", "stdin is not valid UTF-8", {})
    lines = [line for line in text.splitlines() if line.strip() != ""]
    if len(lines) != 1:
        raise OrderError(
            "INVALID_INPUT", "expected exactly one non-empty JSON line on stdin", {}
        )

    def _reject_constant(name: str):
        raise ValueError(f"non-finite constant {name}")

    try:
        value = json.loads(lines[0], parse_constant=_reject_constant)
    except ValueError:
        raise OrderError("INVALID_INPUT", "stdin is not a valid JSON object", {})
    if not isinstance(value, dict):
        raise OrderError("INVALID_INPUT", "stdin JSON must be an object", {})
    return value


def _run(argv: list[str]) -> int:
    try:
        if len(argv) != 3 or argv[0] != "--db":
            raise OrderError(
                "INVALID_INPUT", "usage: python -m src.order_fulfillment --db <path> <command>", {}
            )
        db_path, command = argv[1], argv[2]
        if command not in _FIELDS:
            raise OrderError(
                "INVALID_INPUT", "unknown command", {"command": command}
            )
        request = _read_stdin_object()
        if set(request) != _FIELDS[command]:
            raise OrderError(
                "INVALID_INPUT",
                "request fields do not match command",
                {"command": command, "expected": sorted(_FIELDS[command])},
            )
        service = OrderService(
            db_path, clock=time.time, id_factory=lambda: uuid.uuid4().hex
        )
        if command == "stock":
            result = service.set_stock(request["sku"], request["quantity"])
        elif command == "create":
            result = service.create_order(request["idempotency_key"], request["items"])
        elif command == "pay":
            result = service.pay_order(
                request["order_id"], request["payment_id"], request["amount_cents"]
            )
        elif command == "cancel":
            result = service.cancel_order(request["order_id"])
        elif command == "ship":
            result = service.ship_order(request["order_id"])
        else:
            result = service.get_order(request["order_id"])
    except OrderError as err:
        return _emit_error(err)
    except Exception:
        return _emit_error(OrderError("STORAGE_ERROR", "unexpected internal failure", {}))
    return _emit({"ok": True, "result": result}, 0)


def main() -> None:
    sys.exit(_run(sys.argv[1:]))


if __name__ == "__main__":
    main()

