"""Filesystem-backed durable delivery spool with worker leases."""

from __future__ import annotations

import hmac
import json
import math
import os
import secrets
import time
import uuid
from dataclasses import dataclass

if os.name == "nt":
    import msvcrt
else:
    import fcntl

__all__ = ["Limits", "Spool", "SpoolError"]

_STATE_NAME = "state.json"
_LOCK_NAME = "state.lock"
_STATUSES = ("pending", "leased", "acked", "dead")
_PUBLIC_FIELDS = {"attempts", "available_at", "last_error", "payload", "sequence", "status"}
_LEASE_FIELDS = ("expires_at", "lease_token", "worker_id")


@dataclass(frozen=True)
class Limits:
    max_messages: int = 10000
    max_payload_bytes: int = 65536
    max_attempts: int = 5
    lease_seconds: float = 30.0
    retry_delay: float = 10.0


class SpoolError(Exception):
    """Stable spool-domain error with a code, message, and details."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        super().__init__(message)
        self.code = code
        self.message = message
        self.details = dict(details) if details is not None else {}


def _is_number(value: object) -> bool:
    return (
        not isinstance(value, bool)
        and isinstance(value, (int, float))
        and math.isfinite(value)
    )


def _require_id(name: str, value: object) -> str:
    if not isinstance(value, str) or value.strip() == "":
        raise SpoolError(
            "INVALID_INPUT",
            f"{name} must be a non-empty, non-whitespace string",
            {"field": name},
        )
    return value


def _validate_payload(value: object) -> None:
    kind = type(value)
    if value is None or kind is bool or kind is str or kind is int:
        return
    if kind is float:
        if not math.isfinite(value):
            raise SpoolError("INVALID_INPUT", "payload numbers must be finite", {})
        return
    if kind is list:
        for item in value:
            _validate_payload(item)
        return
    if kind is dict:
        for key, item in value.items():
            if type(key) is not str:
                raise SpoolError(
                    "INVALID_INPUT", "payload object keys must be strings", {}
                )
            _validate_payload(item)
        return
    raise SpoolError(
        "INVALID_INPUT", "payload must use only JSON-compatible types", {}
    )


def _canonical(value) -> str:
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False
    )


def _validate_limits(limits: Limits) -> None:
    for field in ("max_messages", "max_payload_bytes", "max_attempts"):
        value = getattr(limits, field)
        if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
            raise SpoolError(
                "INVALID_INPUT", f"limits.{field} must be a positive integer",
                {"field": field},
            )
    lease = limits.lease_seconds
    if not _is_number(lease) or lease <= 0:
        raise SpoolError(
            "INVALID_INPUT", "limits.lease_seconds must be a finite number > 0",
            {"field": "lease_seconds"},
        )
    retry = limits.retry_delay
    if not _is_number(retry) or retry < 0:
        raise SpoolError(
            "INVALID_INPUT", "limits.retry_delay must be a finite number >= 0",
            {"field": "retry_delay"},
        )


def _corrupt(reason: str) -> SpoolError:
    return SpoolError("CORRUPT_STATE", "state file is corrupt", {"reason": reason})


def _validate_record(message_id: str, record: object) -> None:
    if type(record) is not dict:
        raise _corrupt("message record is not an object")
    if not isinstance(message_id, str) or message_id.strip() == "":
        raise _corrupt("invalid message id key")
    status = record.get("status")
    if status not in _STATUSES:
        raise _corrupt("unknown message status")
    expected = set(_PUBLIC_FIELDS)
    if status == "leased":
        expected |= set(_LEASE_FIELDS)
    if set(record) != expected:
        raise _corrupt("unexpected message fields")
    attempts = record["attempts"]
    if isinstance(attempts, bool) or type(attempts) is not int or attempts < 0:
        raise _corrupt("invalid attempts")
    if not _is_number(record["available_at"]):
        raise _corrupt("invalid available_at")
    last_error = record["last_error"]
    if last_error is not None and type(last_error) is not str:
        raise _corrupt("invalid last_error")
    sequence = record["sequence"]
    if isinstance(sequence, bool) or type(sequence) is not int or sequence < 1:
        raise _corrupt("invalid sequence")
    try:
        _validate_payload(record["payload"])
    except SpoolError:
        raise _corrupt("invalid payload")
    if status == "leased":
        if not _is_number(record["expires_at"]):
            raise _corrupt("invalid expires_at")
        token = record["lease_token"]
        if type(token) is not str or token == "":
            raise _corrupt("invalid lease_token")
        worker = record["worker_id"]
        if type(worker) is not str or worker.strip() == "":
            raise _corrupt("invalid worker_id")


def _parse_state(raw: bytes) -> dict:
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise _corrupt("state is not valid UTF-8")

    def _pairs(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("duplicate key")
            result[key] = value
        return result

    def _constant(name):
        raise ValueError(f"non-finite constant {name}")

    try:
        state = json.loads(text, object_pairs_hook=_pairs, parse_constant=_constant)
    except ValueError:
        raise _corrupt("state is not valid JSON")
    if type(state) is not dict:
        raise _corrupt("state root is not an object")
    version = state.get("schema_version")
    if isinstance(version, bool) or version != 1:
        raise SpoolError(
            "SCHEMA_MISMATCH", "unknown state schema version",
            {"schema_version": version if isinstance(version, (int, str)) else None},
        )
    if set(state) != {"schema_version", "next_sequence", "messages"}:
        raise _corrupt("unexpected top-level fields")
    next_sequence = state["next_sequence"]
    if isinstance(next_sequence, bool) or type(next_sequence) is not int or next_sequence < 1:
        raise _corrupt("invalid next_sequence")
    messages = state["messages"]
    if type(messages) is not dict:
        raise _corrupt("messages is not an object")
    sequences = set()
    for message_id, record in messages.items():
        _validate_record(message_id, record)
        sequence = record["sequence"]
        if sequence in sequences or sequence >= next_sequence:
            raise _corrupt("inconsistent sequence numbers")
        sequences.add(sequence)
    if text != _canonical(state) + "\n":
        raise _corrupt("state is not canonical JSON")
    return state


class Spool:
    """Durable outbox/lease queue stored as one canonical JSON state file."""

    def __init__(self, root, *, clock, limits, lock_timeout, failpoint):
        if not isinstance(root, (str, os.PathLike)) or os.fspath(root) == "":
            raise SpoolError("INVALID_INPUT", "root must be a filesystem path", {})
        if not callable(clock):
            raise SpoolError("INVALID_DEPENDENCY", "clock must be callable", {})
        if type(limits) is not Limits:
            raise SpoolError("INVALID_INPUT", "limits must be a Limits instance", {})
        _validate_limits(limits)
        if not _is_number(lock_timeout) or lock_timeout < 0:
            raise SpoolError(
                "INVALID_INPUT", "lock_timeout must be a finite number >= 0", {}
            )
        if failpoint is not None and not callable(failpoint):
            raise SpoolError(
                "INVALID_DEPENDENCY", "failpoint must be callable or None", {}
            )
        self._root = os.fspath(root)
        self._clock = clock
        self._limits = limits
        self._lock_timeout = lock_timeout
        self._failpoint = failpoint

    # -- infrastructure ----------------------------------------------------

    def _call_failpoint(self, name: str) -> None:
        if self._failpoint is not None:
            self._failpoint(name)

    def _read_clock(self):
        try:
            value = self._clock()
        except Exception as exc:
            raise SpoolError(
                "INVALID_DEPENDENCY", "clock raised an exception", {"error": str(exc)}
            )
        if not _is_number(value):
            raise SpoolError(
                "INVALID_DEPENDENCY", "clock must return a finite number", {}
            )
        return value

    def _acquire_lock(self) -> int:
        lock_path = os.path.join(self._root, _LOCK_NAME)
        try:
            fd = os.open(lock_path, os.O_RDWR | os.O_CREAT, 0o644)
        except OSError as exc:
            raise SpoolError(
                "INTERNAL_ERROR", "cannot open lock file", {"error": str(exc)}
            )
        deadline = time.monotonic() + self._lock_timeout
        while True:
            try:
                if os.name == "nt":
                    os.lseek(fd, 0, os.SEEK_SET)
                    msvcrt.locking(fd, msvcrt.LK_NBLCK, 1)
                else:
                    fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                return fd
            except OSError:
                if time.monotonic() >= deadline:
                    os.close(fd)
                    raise SpoolError(
                        "LOCK_TIMEOUT", "could not acquire the state lock", {}
                    )
                time.sleep(0.005)

    def _release_lock(self, fd: int) -> None:
        try:
            if os.name == "nt":
                os.lseek(fd, 0, os.SEEK_SET)
                msvcrt.locking(fd, msvcrt.LK_UNLCK, 1)
            else:
                fcntl.flock(fd, fcntl.LOCK_UN)
        except OSError:
            pass
        finally:
            try:
                os.close(fd)
            except OSError:
                pass

    def _load_state(self) -> dict:
        state_path = os.path.join(self._root, _STATE_NAME)
        try:
            with open(state_path, "rb") as handle:
                raw = handle.read()
        except FileNotFoundError:
            raise SpoolError("NOT_INITIALIZED", "spool is not initialized", {})
        except OSError as exc:
            raise SpoolError(
                "INTERNAL_ERROR", "cannot read state file", {"error": str(exc)}
            )
        return _parse_state(raw)

    def _fsync_root(self) -> None:
        try:
            dir_fd = os.open(self._root, os.O_RDONLY)
        except OSError:
            return
        try:
            os.fsync(dir_fd)
        except OSError:
            pass
        finally:
            os.close(dir_fd)

    def _run(self, handler, *, initialize: bool = False):
        if initialize:
            try:
                os.makedirs(self._root, exist_ok=True)
            except OSError as exc:
                raise SpoolError(
                    "INTERNAL_ERROR", "cannot create spool root", {"error": str(exc)}
                )
        if not os.path.isdir(self._root):
            raise SpoolError(
                "NOT_INITIALIZED", "spool root does not exist", {"root": self._root}
            )
        lock_fd = self._acquire_lock()
        tmp_path = None
        try:
            self._call_failpoint("after_lock")
            state_path = os.path.join(self._root, _STATE_NAME)
            if initialize:
                if os.path.exists(state_path):
                    raise SpoolError(
                        "ALREADY_INITIALIZED", "spool is already initialized", {}
                    )
                state = {"schema_version": 1, "next_sequence": 1, "messages": {}}
                result, changed = handler(state)
            else:
                state = self._load_state()
                result, changed = handler(state)
            if changed:
                data = (_canonical(state) + "\n").encode("utf-8")
                tmp_path = os.path.join(
                    self._root, f".state.{os.getpid()}.{uuid.uuid4().hex}.tmp"
                )
                try:
                    with open(tmp_path, "xb") as handle:
                        handle.write(data)
                        handle.flush()
                        os.fsync(handle.fileno())
                except OSError as exc:
                    raise SpoolError(
                        "INTERNAL_ERROR", "cannot write state", {"error": str(exc)}
                    )
                self._call_failpoint("before_replace")
                try:
                    os.replace(tmp_path, state_path)
                except OSError as exc:
                    raise SpoolError(
                        "INTERNAL_ERROR", "cannot publish state", {"error": str(exc)}
                    )
                tmp_path = None
                self._call_failpoint("after_replace")
                self._fsync_root()
            return result
        finally:
            if tmp_path is not None:
                try:
                    os.remove(tmp_path)
                except OSError:
                    pass
            self._release_lock(lock_fd)

    def _public(self, message_id: str, record: dict) -> dict:
        return {
            "message_id": message_id,
            "payload": json.loads(_canonical(record["payload"])),
            "status": record["status"],
            "available_at": record["available_at"],
            "sequence": record["sequence"],
            "attempts": record["attempts"],
            "last_error": record["last_error"],
        }

    def _authorized_record(self, state: dict, message_id: str, lease_token: str) -> dict:
        record = state["messages"].get(message_id)
        if record is None:
            raise SpoolError(
                "NOT_FOUND", "message not found", {"message_id": message_id}
            )
        if record["status"] != "leased":
            raise SpoolError(
                "INVALID_STATE",
                "message is not currently leased",
                {"message_id": message_id, "status": record["status"]},
            )
        if not hmac.compare_digest(
            record["lease_token"].encode("utf-8"), lease_token.encode("utf-8")
        ):
            raise SpoolError(
                "UNAUTHORIZED", "lease token does not match", {"message_id": message_id}
            )
        return record

    # -- public API --------------------------------------------------------

    def initialize(self) -> dict:
        def handler(state):
            return (
                {"schema_version": 1, "next_sequence": 1, "messages": {}},
                True,
            )

        return self._run(handler, initialize=True)

    def enqueue(self, message_id: str, payload, available_at=None) -> dict:
        _require_id("message_id", message_id)
        _validate_payload(payload)
        canonical_payload = _canonical(payload)
        if len(canonical_payload.encode("utf-8")) > self._limits.max_payload_bytes:
            raise SpoolError(
                "CAPACITY_EXCEEDED",
                "payload exceeds max_payload_bytes",
                {"max_payload_bytes": self._limits.max_payload_bytes},
            )
        if available_at is not None and not _is_number(available_at):
            raise SpoolError(
                "INVALID_INPUT", "available_at must be a finite number", {}
            )

        def handler(state):
            messages = state["messages"]
            record = messages.get(message_id)
            if record is not None:
                same_payload = _canonical(record["payload"]) == canonical_payload
                same_available = (
                    available_at is None or record["available_at"] == available_at
                )
                if same_payload and same_available:
                    return (self._public(message_id, record), False)
                raise SpoolError(
                    "IDEMPOTENCY_CONFLICT",
                    "message id reused with a different request",
                    {"message_id": message_id},
                )
            if len(messages) >= self._limits.max_messages:
                raise SpoolError(
                    "CAPACITY_EXCEEDED",
                    "max_messages reached",
                    {"max_messages": self._limits.max_messages},
                )
            when = available_at if available_at is not None else self._read_clock()
            sequence = state["next_sequence"]
            state["next_sequence"] = sequence + 1
            record = {
                "attempts": 0,
                "available_at": when,
                "last_error": None,
                "payload": json.loads(canonical_payload),
                "sequence": sequence,
                "status": "pending",
            }
            messages[message_id] = record
            return (self._public(message_id, record), True)

        return self._run(handler)

    def claim(self, worker_id: str) -> dict | None:
        _require_id("worker_id", worker_id)

        def handler(state):
            now = self._read_clock()
            best_key = None
            best_id = None
            for message_id, record in state["messages"].items():
                if record["status"] != "pending" or record["available_at"] > now:
                    continue
                key = (record["available_at"], record["sequence"], message_id)
                if best_key is None or key < best_key:
                    best_key = key
                    best_id = message_id
            if best_id is None:
                return (None, False)
            record = state["messages"][best_id]
            record["attempts"] += 1
            record["status"] = "leased"
            record["worker_id"] = worker_id
            record["lease_token"] = secrets.token_hex(16)
            record["expires_at"] = now + self._limits.lease_seconds
            result = self._public(best_id, record)
            result["lease_token"] = record["lease_token"]
            return (result, True)

        return self._run(handler)

    def ack(self, message_id: str, lease_token: str) -> dict:
        _require_id("message_id", message_id)
        if not isinstance(lease_token, str):
            raise SpoolError("INVALID_INPUT", "lease_token must be a string", {})

        def handler(state):
            record = self._authorized_record(state, message_id, lease_token)
            record["status"] = "acked"
            for field in _LEASE_FIELDS:
                record.pop(field, None)
            return (self._public(message_id, record), True)

        return self._run(handler)

    def fail(self, message_id: str, lease_token: str, error: str) -> dict:
        _require_id("message_id", message_id)
        if not isinstance(lease_token, str):
            raise SpoolError("INVALID_INPUT", "lease_token must be a string", {})
        if not isinstance(error, str) or error == "":
            raise SpoolError(
                "INVALID_INPUT", "error must be a non-empty string", {"field": "error"}
            )

        def handler(state):
            record = self._authorized_record(state, message_id, lease_token)
            record["last_error"] = error
            for field in _LEASE_FIELDS:
                record.pop(field, None)
            if record["attempts"] >= self._limits.max_attempts:
                record["status"] = "dead"
            else:
                record["status"] = "pending"
                record["available_at"] = self._read_clock() + self._limits.retry_delay
            return (self._public(message_id, record), True)

        return self._run(handler)

    def recover(self) -> dict:
        def handler(state):
            now = self._read_clock()
            recovered = 0
            for record in state["messages"].values():
                if record["status"] != "leased" or now < record["expires_at"]:
                    continue
                for field in _LEASE_FIELDS:
                    record.pop(field, None)
                if record["attempts"] >= self._limits.max_attempts:
                    record["status"] = "dead"
                else:
                    record["status"] = "pending"
                    record["available_at"] = now
                recovered += 1
            return ({"recovered": recovered}, recovered > 0)

        return self._run(handler)

    def get(self, message_id: str) -> dict:
        _require_id("message_id", message_id)

        def handler(state):
            record = state["messages"].get(message_id)
            if record is None:
                raise SpoolError(
                    "NOT_FOUND", "message not found", {"message_id": message_id}
                )
            return (self._public(message_id, record), False)

        return self._run(handler)

    def list_messages(self, status=None) -> list[dict]:
        if status is not None and status not in _STATUSES:
            raise SpoolError(
                "INVALID_INPUT", "status must be one of the message statuses",
                {"field": "status"},
            )

        def handler(state):
            selected = [
                (record["available_at"], record["sequence"], message_id, record)
                for message_id, record in state["messages"].items()
                if status is None or record["status"] == status
            ]
            selected.sort(key=lambda entry: (entry[0], entry[1], entry[2]))
            return (
                [self._public(message_id, record) for _, _, message_id, record in selected],
                False,
            )

        return self._run(handler)

