"""Delivery spool JSON CLI entry point."""

from __future__ import annotations

import json
import sys
import time

from . import Limits, Spool, SpoolError

_EXIT3_CODES = {"CORRUPT_STATE", "LOCK_TIMEOUT", "INTERNAL_ERROR"}

# command -> (required fields, optional fields, stdin may be omitted)
_COMMANDS = {
    "init": (set(), set(), True),
    "enqueue": ({"message_id", "payload"}, {"available_at"}, False),
    "claim": ({"worker_id"}, set(), False),
    "ack": ({"message_id", "lease_token"}, set(), False),
    "fail": ({"message_id", "lease_token", "error"}, set(), False),
    "recover": (set(), set(), True),
    "show": ({"message_id"}, set(), False),
    "list": (set(), {"status"}, True),
}


def _emit(obj: dict, exit_code: int) -> int:
    data = json.dumps(
        obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False
    )
    sys.stdout.buffer.write(data.encode("utf-8") + b"\n")
    sys.stdout.buffer.flush()
    return exit_code


def _emit_error(err: SpoolError) -> int:
    envelope = {
        "ok": False,
        "error": {"code": err.code, "message": err.message, "details": err.details},
    }
    exit_code = 3 if err.code in _EXIT3_CODES else 2
    try:
        return _emit(envelope, exit_code)
    except (TypeError, ValueError):
        envelope["error"]["details"] = {}
        return _emit(envelope, exit_code)


def _read_stdin_object(allow_empty: bool) -> dict:
    try:
        text = sys.stdin.buffer.read().decode("utf-8")
    except UnicodeDecodeError:
        raise SpoolError("INVALID_INPUT", "stdin is not valid UTF-8", {})
    lines = [line for line in text.splitlines() if line.strip() != ""]
    if not lines:
        if allow_empty:
            return {}
        raise SpoolError(
            "INVALID_INPUT", "expected exactly one non-empty JSON line on stdin", {}
        )
    if len(lines) != 1:
        raise SpoolError(
            "INVALID_INPUT", "expected exactly one non-empty JSON line on stdin", {}
        )

    def _reject_constant(name: str):
        raise ValueError(f"non-finite constant {name}")

    try:
        value = json.loads(lines[0], parse_constant=_reject_constant)
    except ValueError:
        raise SpoolError("INVALID_INPUT", "stdin is not a valid JSON object", {})
    if not isinstance(value, dict):
        raise SpoolError("INVALID_INPUT", "stdin JSON must be an object", {})
    return value


def _run(argv: list[str]) -> int:
    try:
        if len(argv) != 3 or argv[0] != "--root":
            raise SpoolError(
                "INVALID_INPUT",
                "usage: python -m src.delivery_spool --root <path> <command>",
                {},
            )
        root, command = argv[1], argv[2]
        if command not in _COMMANDS:
            raise SpoolError("INVALID_INPUT", "unknown command", {"command": command})
        required, optional, allow_empty = _COMMANDS[command]
        request = _read_stdin_object(allow_empty)
        keys = set(request)
        if not required <= keys or not keys <= (required | optional):
            raise SpoolError(
                "INVALID_INPUT",
                "request fields do not match command",
                {"command": command, "required": sorted(required)},
            )
        spool = Spool(
            root,
            clock=time.time,
            limits=Limits(),
            lock_timeout=10.0,
            failpoint=None,
        )
        if command == "init":
            result = spool.initialize()
        elif command == "enqueue":
            result = spool.enqueue(
                request["message_id"],
                request["payload"],
                available_at=request.get("available_at"),
            )
        elif command == "claim":
            result = spool.claim(request["worker_id"])
        elif command == "ack":
            result = spool.ack(request["message_id"], request["lease_token"])
        elif command == "fail":
            result = spool.fail(
                request["message_id"], request["lease_token"], request["error"]
            )
        elif command == "recover":
            result = spool.recover()
        elif command == "show":
            result = spool.get(request["message_id"])
        else:
            result = spool.list_messages(status=request.get("status"))
    except SpoolError as err:
        return _emit_error(err)
    except Exception:
        return _emit_error(
            SpoolError("INTERNAL_ERROR", "unexpected internal failure", {})
        )
    return _emit({"ok": True, "result": result}, 0)


def main() -> None:
    sys.exit(_run(sys.argv[1:]))


if __name__ == "__main__":
    main()

